CREATE TABLE "WorkloadCapacity" ("id" TEXT PRIMARY KEY, "employeeId" TEXT NOT NULL REFERENCES "Employee"("id") ON DELETE CASCADE, "week" VARCHAR(10) NOT NULL, "scheduledHours" DOUBLE PRECISION NOT NULL CHECK ("scheduledHours" >= 0 AND "scheduledHours" <= 168), "timeOffHours" DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK ("timeOffHours" >= 0 AND "timeOffHours" <= "scheduledHours"), "updatedById" TEXT NOT NULL, UNIQUE ("employeeId", "week"));
ALTER TABLE "ProjectStaff" ADD COLUMN "weeklyHours" DOUBLE PRECISION CHECK ("weeklyHours" > 0 AND "weeklyHours" <= 168), ADD COLUMN "allocationStart" TIMESTAMP(3), ADD COLUMN "allocationEnd" TIMESTAMP(3);